// 테스트 시 true로 변경하면 발송 실패 상황을 재현할 수 있음
const FORCE_FAIL = false;

const data = $json;

if (FORCE_FAIL) {
  return {
    json: {
      ...data,

      send_success: false,
      provider: 'MOCK',
      provider_message_id: null,
      provider_status: 'FAILED',
      error_code: 'MOCK_SEND_FAILED'
    }
  };
}

return {
  json: {
    ...data,

    send_success: true,
    provider: 'MOCK',
    provider_message_id: `MOCK-${data.message_id}`,
    provider_status: 'ACCEPTED',
    error_code: null
  }
};

const result = $input.first().json;

return [{
  json: {
    success: true,
    feature_id: 'F-07',
    status: 'sent',
    send_completed: true,
    message_id: result.message_id ?? null,
    schedule_id: result.schedule_id ?? null
  }
}];

const result = $input.first().json;

return [{
  json: {
    success: false,
    feature_id: 'F-07',
    status: 'failed',
    send_completed: false,
    reason: 'send_failed',
    message_id: result.message_id ?? null,
    schedule_id: result.schedule_id ?? null
  }
}];

const input = $('[조회/선점] 발송 메시지 확보').first().json;

return [{
  json: {
    success: false,
    feature_id: 'F-07',
    status: 'failed',
    send_completed: false,
    reason: 'claim_failed',
    message_id: input.message_id ?? null,
    schedule_id: input.schedule_id ?? null
  }
}];
